begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
create temporary table tap_results(line text);grant all on tap_results to authenticated;
create temporary table saved(name text primary key,data jsonb);grant all on saved to authenticated;
create function pg_temp.i(n integer) returns uuid language sql immutable as $$select ('92000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid$$;
create function pg_temp.login(n integer) returns text language sql as $$select set_config('request.jwt.claims',jsonb_build_object('sub',pg_temp.i(n),'session_id',pg_temp.i(n),'role','authenticated','is_anonymous',false)::text,true)$$;
create function pg_temp.ctx() returns jsonb language sql as $$select jsonb_build_object('organizationId',pg_temp.i(1),'branchId',pg_temp.i(101))$$;
create function pg_temp.book() returns jsonb language sql as $$select public.agri_command('credit_book',pg_temp.ctx())$$;
create function pg_temp.policy(n integer default 701) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('clientId',pg_temp.i(801),'requestId',pg_temp.i(n),'name','TEST Farmer','phone','TEST desk','address','TEST Magpet','tin','TEST only','enabled',true,'limit',1000000,'terms',jsonb_build_array(30,60,90),'expectedVersion',0,'approved',true,'reason','TEST owner-approved credit')$$;
create function pg_temp.sale(n integer default 901,t integer default 60) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'version',2,'clientId',pg_temp.i(801),'term',t,'expectedDueOn',(now() at time zone 'Asia/Manila')::date+t,'officialReference','TEST-BOOK-'||n,'manualInvoiceConfirmed',true,'cashierId',auth.uid(),'deviceId',pg_temp.i(501),'shiftId',(select id from public.cashier_shifts where closed_at is null),'total',100000,'cashReceived',20000,'items',jsonb_build_array(jsonb_build_object('productId',pg_temp.i(301),'unitId',pg_temp.i(401),'batchId',null,'name','TEST feeds','unitName','Kilo','quantity','10','factor','1','unitPrice',10000,'unitCost',5000,'priceVersion',1,'lineTotal',100000)))$$;
create function pg_temp.payment(n integer default 1001,a bigint default 30000) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'saleId',pg_temp.i(901),'shiftId',(select id from public.cashier_shifts where closed_at is null),'amount',a,'reference','TEST collection','reason','TEST exact retained cash')$$;
-- Synthetic setup is prepended from the existing rollback-only fixture.
create function pg_temp.sbill(n integer default 1001,days integer default 30,value bigint default 100000) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'supplierId',pg_temp.i(601),'reference','TEST-SUP-'||n,'issuedOn',(now() at time zone 'Asia/Manila')::date,'term',days,'expectedDueOn',(now() at time zone 'Asia/Manila')::date+days,'amount',value,'receiptId',null,'replacesId',null,'reason','TEST five bags bought for the store','confirmed',true)$$;
create function pg_temp.sstate(n integer default 1001) returns jsonb language sql as $$select public.agri_command('supplier_invoice_history',pg_temp.ctx()||jsonb_build_object('billId',pg_temp.i(n)))->'invoice'$$;
create function pg_temp.sbook(data jsonb default '{}') returns jsonb language sql as $$select public.agri_command('supplier_account_book',pg_temp.ctx()||data)$$;
create function pg_temp.spay(n integer default 1101,bill integer default 1001,value bigint default 40000) returns jsonb language sql as $$select pg_temp.ctx()||jsonb_build_object('requestId',pg_temp.i(n),'billId',pg_temp.i(bill),'expectedVersion',pg_temp.sstate(bill)->'version','expectedBalance',pg_temp.sstate(bill)->'balance','amount',value,'method','bank','paidOn',(now() at time zone 'Asia/Manila')::date,'reference','TEST-PAY-'||n,'reason','TEST verified supplier bank payment','confirmed',true)$$;
set local role authenticated;select pg_temp.login(11);
select public.agri_command('supplier_record_invoice',pg_temp.sbill(1002,60));select public.agri_command('supplier_record_invoice',pg_temp.sbill(1003,90));
select public.agri_command('supplier_record_payment',pg_temp.spay(1102,1001,60000));
select public.agri_command('supplier_reverse_entry',(select data from saved where name='reverse'));
select public.agri_command('supplier_credit_note',pg_temp.spay(1104,1001,40000)||'{"method":null}');
select public.agri_command('supplier_void_invoice',pg_temp.spay(1201,1002));
select public.agri_command('supplier_record_invoice',pg_temp.sbill(1004,60,90000)||jsonb_build_object('reference','TEST-SUP-1002','replacesId',pg_temp.i(1002)));
select public.agri_command('supplier_record_invoice',pg_temp.sbill(1005,30)||jsonb_build_object('issuedOn',(now() at time zone 'Asia/Manila')::date-31,'expectedDueOn',(now() at time zone 'Asia/Manila')::date-1));
select pg_temp.login(12);
select pg_temp.login(13);
select pg_temp.login(14);
reset role;
set local role authenticated;select pg_temp.login(15);
select pg_temp.login(11);
do $$begin for n in 2000..2051 loop perform public.agri_command('supplier_record_invoice',pg_temp.sbill(n)||jsonb_build_object('reference','TEST-PAGE-'||n));end loop;end$$;
select line from tap_results;select * from finish();rollback;
